def S(k):
    # N=11 vertices. k vertices have degree 10, 11-k vertices have degree k.
    if k == 0 or k == 11:
        return 0
    return k * (11 - k) * abs(10 - k)

values = {}
for k in range(1, 11):
    values[k] = S(k)

print(f"S(k) values: {values}")
print(f"Maximum S found: {max(values.values())}")
